def classify_existing_wallets_as_promotional(apps, schema_editor):
    Wallet = apps.get_model('livestreams', 'Wallet')
    WalletTransaction = apps.get_model('livestreams', 'WalletTransaction')
    alias = schema_editor.connection.alias
    wallets = list(Wallet.objects.using(alias).all().iterator())
    transactions = []
    for wallet in wallets:
        wallet.promotional_balance = wallet.balance
        wallet.purchased_balance = 0
        transactions.append(WalletTransaction(
            wallet_id=wallet.pk,
            transaction_type='legacy_promotional',
            credits_delta=wallet.balance,
            promotional_credits_delta=wallet.balance,
            purchased_credits_delta=0,
            balance_after=wallet.balance,
            reference=f'legacy-promotional:{wallet.pk}',
        ))
    Wallet.objects.using(alias).bulk_update(wallets, ('promotional_balance', 'purchased_balance'))
    WalletTransaction.objects.using(alias).bulk_create(transactions, batch_size=500)


